EXP2_RESULTS = [
("P", "Ten child trials (seven from 4-year-olds and three from 5-year-olds) had no recorded response and are excluded, leaving 1,030 responses (4-year-olds: 313; 5-year-olds: 317; adults: 400). Both models converged (R̂ ≤ 1.003, no divergent transitions). Figure 5 shows the proportions of responses that contained an RVC and that mentioned the target result, and Table 2 shows the distribution of response categories."),
("FIG", "fig5"),
("H3", "RVC Use"),
("P", "Responses contained an RVC more often for full-result than for zero-result events in all groups (4-year-olds: 15% vs. 9%; 5-year-olds: 29% vs. 10%; adults: 56% vs. 29%). In the model, this difference was credible for 5-year-olds (log-odds: 1.92, 95% CrI [0.82, 3.13], *p*(> 0) > .99) and adults (1.87 [0.97, 2.84], *p*(> 0) > .99) but uncertain for 4-year-olds (0.81 [−0.37, 2.01], *p*(> 0) = .92), who produced few RVCs in either condition. On the log-odds scale, the effect of result realization did not differ credibly between children and adults (−0.50 [−1.57, 0.54]). Adults produced RVCs more often than children (difference in predicted proportion, averaged over result conditions: 0.30 [0.15, 0.46]), and 5-year-olds slightly more often than 4-year-olds (0.06 [0.00, 0.17]). RVCs in zero-result events usually appeared in negated or potential forms (e.g., *méi zá-kāi* \"did not smash open\"; *qiāo bù kāi* \"knock-cannot-open\") or, in adults, as the object of an attempt verb (e.g., *shìtú sī-kāi* \"tried to tear open\")."),
("H3", "Mention of the Target Result"),
("P", "The target result was mentioned more often for full-result than for zero-result events in all groups (4-year-olds: 29% vs. 12%; 5-year-olds: 40% vs. 11%; adults: 67% vs. 28%). The difference was credible in each group (log-odds: 1.43 [0.28, 2.67], *p*(> 0) = .99; 2.32 [1.20, 3.59], *p*(> 0) > .99; and 2.74 [1.65, 3.87], *p*(> 0) > .99, respectively), and it tended to be smaller in children than in adults (−0.84 [−1.75, 0.03]). Adults mentioned the target result more often than children (0.27 [0.15, 0.39]). In zero-result events, adults who mentioned the target result usually denied it (20% of zero-result responses) or presented it as the actor's goal (7%); children denied it in 8% of zero-result responses. Responses affirming the target result in a zero-result event were rare (4-year-olds: 5 responses, 3%; 5-year-olds: 6, 4%; adults: 2, 1%)."),
("H3", "Response Categories"),
("P", "Among responses without an RVC (Table 2), action-only responses predominated in all groups and in both result conditions (67%–90%). In full-result events, children's descriptions more often named the action alone than adults' (all responses: 62% and 53% vs. 31%), whereas responses expressing the action and the target result in separate predicates (e.g., *huīwǔ-le jǐ xià, làzhú miè le* \"waved it a few times, and the candle went out\") made up 13%–14% of children's and 26% of adults' responses without an RVC. Responses mentioning only the target result were rare (0%–6%). Thus, children did not express the target result in separate predicates or without the action more often than adults; their lower RVC use went together with less frequent mention of the result. In zero-result events, separate-predicate and result-only responses were rare in all groups (≤ 5% of responses without an RVC). Because several cells contain few responses, these proportions are reported descriptively."),
("TABLE2", ""),
("P", "Restricting the analyses to the eight retained pairs did not change these patterns (RVC use, full minus zero, log-odds: 4-year-olds: 0.62 [−0.61, 1.90]; 5-year-olds: 1.81 [0.66, 3.06]; adults: 2.01 [1.00, 3.08]). Descriptively, in zero-result events RVCs were produced somewhat more often for stronger- than for weaker-association actions (4-year-olds: 12% vs. 6%; 5-year-olds: 12% vs. 6%; adults: 33% vs. 25%), mostly in negated or attempt constructions; this comparison was not planned and is not modeled. ⟦产出编码为依据逐项关键词表的规则编码初稿，待人工核对和第二编码者编码后更新以上数值⟧"),
]

TABLE2_CAPTION = ("Table 2", "Response Categories by Result Realization and Age Group in Experiment 2 (Percentages of Responses)")
TABLE2_HEADER = ["Age group", "Result", "*n*", "RVC", "Separate predicates", "Result only", "Action only", "Neither"]
TABLE2_NOTE = "*Note.* RVC = action and target result expressed in an RVC, affirmed or negated. Responses containing an RVC that did not express the target result (e.g., an RVC with a different result) are classified by the remaining information; therefore, the RVC column can be lower than the proportion of responses containing an RVC reported in the text. All 10 pairs are included."
